CREATE OR REPLACE FUNCTION public.seed_jar_opened(p_world uuid, p_uid uuid, p_target jsonb)
 RETURNS item
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(
    (select n from carried(p_world, p_uid, target_item(p_target)) n where n.def = 'ancient_seed_jar'),
    (select i from item i
      where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid
        and i.def = 'ancient_seed_jar' and not i.locked
      order by i.id limit 1))
$function$
